using System;using System.IO;using System.Linq;using System.Drawing;using System.Drawing.Imaging;using System.Threading;using Prometheus;
class Demo {static void Main(string[] args){string root=Path.GetFullPath(args[0]);Tools.Root=root;string dir=Path.Combine(root,"demo");Directory.CreateDirectory(dir);using(var image=new Bitmap(640,360,PixelFormat.Format32bppArgb)){using(var g=Graphics.FromImage(image)){g.Clear(Color.Transparent);using(var brush=new SolidBrush(Color.FromArgb(210,25,28,32)))g.FillRectangle(brush,24,268,440,65);using(var pen=new Pen(Color.FromArgb(255,156,44),4))g.DrawLine(pen,24,268,24,333);using(var font=new Font("Segoe UI",18,FontStyle.Bold))g.DrawString("PROMETHEUS",font,Brushes.White,42,278);using(var font=new Font("Segoe UI",10))g.DrawString("Montaje de prueba · capa PNG transparente",font,Brushes.Silver,44,307);}image.Save(Path.Combine(dir,"grafico.png"));}
var p=Store.New();p.name="Demostración";foreach(string name in new[]{"video.mp4","voz.wav","grafico.png"})p.assets.Add(Media.Inspect(Path.Combine(dir,name),CancellationToken.None));var v=p.Active.tracks.First(t=>t.kind=="video");Media.Insert(p,p.assets[0].id,v.id,0);Media.Insert(p,p.assets[0].id,v.id,3);Media.Insert(p,p.assets[1].id,p.Active.tracks.Where(t=>t.kind=="audio").Last().id,0);Media.Insert(p,p.assets[2].id,p.Active.tracks.Where(t=>t.kind=="video").Last().id,0);var graphic=p.Active.clips.Last();graphic.duration=new Rational(5,1);p.Active.clips.Where(c=>c.asset_id==p.assets[1].id).First().gain_db=-12;Store.Validate(p);foreach(var a in p.assets){a.source.uri=Path.GetFileName(a.source.uri);a.source.relative=true;foreach(var rep in a.representations){rep.locator.path=Path.GetFileName(rep.locator.path);rep.locator.relative=true;}}Store.Save(p,Path.Combine(dir,"Demostracion.prometheus.json"));using(var b=Rendering.Frame(Store.Load(Path.Combine(dir,"Demostracion.prometheus.json")),0.5,CancellationToken.None))b.Save(Path.Combine(dir,"vista-previa.png"));}}
